function arrow(g, x1, y1, x2, y2, color, width, phase, amp) {
  var ag = g.group();
  var line = ag.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var len = Math.max(9, width * 3.2), wid = Math.max(7, width * 2.1);
  var bx = x2 - len * Math.cos(ang), by = y2 - len * Math.sin(ang);
  var px = (wid / 2) * Math.sin(ang), py = -(wid / 2) * Math.cos(ang);
  var head = ag.polygon([[x2, y2], [bx + px, by + py], [bx - px, by - py]]).fill(color).stroke('none');
  if (phase != null) animated.push({ el: ag, phase: phase, base: 0.45, amp: amp == null ? 0.55 : amp });
  return { group: ag, line: line, head: head };
}

function bentArrow(g, d, endAngle, ex, ey, color, width, phase) {
  var ag = g.group();
  ag.path(d).fill('none').stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' });
  var len = Math.max(9, width * 3.2), wid = Math.max(7, width * 2.1);
  var bx = ex - len * Math.cos(endAngle), by = ey - len * Math.sin(endAngle);
  var px = (wid / 2) * Math.sin(endAngle), py = -(wid / 2) * Math.cos(endAngle);
  ag.polygon([[ex, ey], [bx + px, by + py], [bx - px, by - py]]).fill(color).stroke('none');
  if (phase != null) animated.push({ el: ag, phase: phase, base: 0.45, amp: 0.55 });
  return ag;
}

