function attachInfo(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function arrow(g, x1, y1, x2, y2, color, width, phase, amp) {
  var ag = g.group();
  var line = ag.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var len = Math.max(10, width * 3.3), wid = Math.max(8, width * 2.25);
  var bx = x2 - len * Math.cos(ang), by = y2 - len * Math.sin(ang);
  var px = (wid / 2) * Math.sin(ang), py = -(wid / 2) * Math.cos(ang);
  var head = ag.polygon([[x2, y2], [bx + px, by + py], [bx - px, by - py]]).fill(color).stroke('none');
  if (phase != null) animated.push({ el: ag, phase: phase, base: 0.48, amp: amp == null ? 0.52 : amp });
  return { group: ag, line: line, head: head, width0: width };
}

function bentArrow(g, d, endAngle, ex, ey, color, width, phase) {
  var ag = g.group();
  var path = ag.path(d).fill('none').stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' });
  var len = Math.max(10, width * 3.3), wid = Math.max(8, width * 2.25);
  var bx = ex - len * Math.cos(endAngle), by = ey - len * Math.sin(endAngle);
  var px = (wid / 2) * Math.sin(endAngle), py = -(wid / 2) * Math.cos(endAngle);
  ag.polygon([[ex, ey], [bx + px, by + py], [bx - px, by - py]]).fill(color).stroke('none');
  if (phase != null) animated.push({ el: ag, phase: phase, base: 0.48, amp: 0.52 });
  return { group: ag, path: path, width0: width };
}

