function animate(t) {
  if (cycleOn) {
    var speed = 0.00042 + currentRate * 0.000018;
    var p = (t * speed) % 1;
    for (var i = 0; i < animated.length; i++) {
      var a = animated[i];
      var d = Math.abs((((p - a.phase) % 1) + 1) % 1 - 0.5) * 2;
      var pulse = Math.max(0, 1 - d * 2.8);
      a.el.opacity(a.base + a.amp * pulse);
    }
  }
  requestAnimationFrame(animate);
}

