function arrow(g, x1, y1, x2, y2, color, width, phase, amp) {
  var ag = g.group();
  var line = ag.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var len = Math.max(10, width * 3.3), wid = Math.max(8, width * 2.25);
  var bx = x2 - len * Math.cos(ang), by = y2 - len * Math.sin(ang);
  var px = (wid / 2) * Math.sin(ang), py = -(wid / 2) * Math.cos(ang);
  ag.polygon([[x2, y2], [bx + px, by + py], [bx - px, by - py]]).fill(color).stroke('none');
  if (phase != null) animated.push({ el: ag, phase: phase, base: 0.78, amp: amp == null ? 0.22 : amp });
  return { group: ag, line: line, width0: width };
}

function bentArrow(g, d, endAngle, ex, ey, color, width, phase) {
  var ag = g.group();
  var path = ag.path(d).fill('none').stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' });
  var len = Math.max(10, width * 3.3), wid = Math.max(8, width * 2.25);
  var bx = ex - len * Math.cos(endAngle), by = ey - len * Math.sin(endAngle);
  var px = (wid / 2) * Math.sin(endAngle), py = -(wid / 2) * Math.cos(endAngle);
  ag.polygon([[ex, ey], [bx + px, by + py], [bx - px, by - py]]).fill(color).stroke('none');
  if (phase != null) animated.push({ el: ag, phase: phase, base: 0.78, amp: 0.22 });
  return { group: ag, path: path, width0: width };
}

function textHalo(g, s, x, y, size, anchor) {
  var t = g.text(s).font({ family: 'Arial, Helvetica, sans-serif', size: size, anchor: anchor || 'middle' })
    .fill('#000').attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 6, 'stroke-linejoin': 'round' });
  t.center(x, y);
  return t;
}

function multiLabel(lines, x, y, size, anchor) {
  var mg = labelGroup.group();
  var gap = size * 1.18;
  var top = y - gap * (lines.length - 1) / 2;
  for (var i = 0; i < lines.length; i++) {
    textHalo(mg, lines[i], x, top + i * gap, size, anchor || 'middle');
  }
  return mg;
}

