  eg.text('−').font({ family: 'Arial, Helvetica, sans-serif', size: r * 2.05, weight: 'bold', anchor: 'middle' })
    .fill('#000').center(x, y - 1);
  if (phase != null) animated.push({ el: eg, phase: phase, base: 0.82, amp: 0.18 });
  attachInfo(eg, 'Electron: blocked by the membrane, so it travels through the outer circuit', 'Electron path',
    'Electrons produced at the anode cannot cross the proton exchange membrane. They are forced through the wire and load, where their motion can do electrical work.');
