function update_hydrogenFeedRate(v) {
  currentRate = Math.max(0, Math.min(100, v));
  var flowW = 3.2 + currentRate / 60;
  for (var i = 0; i < thicknessItems.length; i++) thicknessItems[i].stroke({ width: flowW });
  var wireW = 5 + currentRate / 30;
  for (var j = 0; j < wireLines.length; j++) wireLines[j].stroke({ width: wireW });
  loadBlack.stroke({ width: 27 + currentRate / 20 });
  loadYellow.stroke({ width: 21 + currentRate / 20 });
  flowLayer.opacity(1);
  particleLayer.opacity(1);
}

function toggle_diagramDetail(on) {
  labelGroup.opacity(on ? 1 : 0);
  document.getElementById('diagramDetailVal').textContent = on ? 'Fully labeled' : 'Clean-flow schematic';
}

function toggle_fuelCellCycle(on) {
  cycleOn = on;
  if (!on) {
    for (var i = 0; i < animated.length; i++) animated[i].el.opacity(1);
  }
}

function animate(t) {
  if (cycleOn) {
    var speed = 0.00042 + currentRate * 0.000018;
    var p = (t * speed) % 1;
    for (var i = 0; i < animated.length; i++) {
      var a = animated[i];
      var d = Math.abs((((p - a.phase) % 1) + 1) % 1 - 0.5) * 2;
      var pulse = Math.max(0, 1 - d * 2.8);
      a.el.opacity(a.base + a.amp * pulse);
    }
  }
  requestAnimationFrame(animate);
}

